import pandas as pd# 1. 先定义一份中文英文姓氏列表（可以根据需要继续补充）CHINESE_SURNAMES = {    # 非常常见的    "Wang", "Zhang", "Li", "Liu", "Chen", "Yang", "Huang", "Zhao",    "Wu", "Zhou", "Xu", "Sun", "Ma", "Zhu", "Hu", "Guo", "He", "Gao",    "Lin", "Luo", "Zheng", "Xie", "Song", "Deng", "Cai", "Tian",    "Fang", "Peng", "Cao", "Tan", "Dong", "Yuan", "Xiao", "Yu", "Jiang",    "Xia", "Dai", "Xu", "Hsu", "Qian", "Qiu", "Qin", "Jin",    "Nie", "Miao", "Cui", "Bai", "Han", "Kang", "Hong", "Wei"    # 记得加港澳台/东南亚常见写法    "Chan", "Tan", "Lim", "Lam", "Leung", "Cheung", "Cheng", "Chong",    "Chow", "Chou", "Tsai", "Tsang", "Hsu", "Ho", "Koo", "Kuo", "Goh",    "Yip", "Yap", "Yeo", "Yong", "Toh", "Pang", "Poon",    # 需要的可以往里继续加。。。}def extract_surname(fullname: str) -> str:    """    从形如 'Wang, Zhong Lin' 的字符串中提取姓氏 'Wang'，    并做 strip + Title() 统一格式。    """    if not isinstance(fullname, str):        return ""    # 防止没有逗号的极端情况    parts = fullname.split(",", 1)    surname = parts[0].strip()    # 统一成首字母大写，其余小写：WANG / wAnG -> Wang    return surname.title()def main():    # 2. 读取 Excel（改成你的文件名、sheet 名）    input_file = "Table_1_Authors_career_2024_pubs_since_1788_wopp_extracted_202508.xlsx"    sheet_name = "Data"    auth_col = "authfull" # TODO: 换成实际的列名    df = pd.read_excel(input_file, sheet_name=sheet_name)    # 3. 提取姓氏    df["surname_raw"] = df[auth_col].apply(extract_surname)    # 4. 判断是否在中文姓氏集合里    df["is_chinese_surname"] = df["surname_raw"].isin(CHINESE_SURNAMES)    # 也可以直接给出中文标签列    df["possible_chinese"] = df["is_chinese_surname"].apply(        lambda x: "可能华裔" if x else ""    )    # 5. 保存结果（可以存 Excel 或 CSV）    output_file = "scientists_tagged.xlsx"    df.to_excel(output_file, index=False)    print(f"处理完成，结果已保存到：{output_file}")    print(df[["authfull", "surname_raw", "possible_chinese"]].head(20))if __name__ == "__main__":    main()